changeSet.sql:
UPDATE theme
SET tokens = tokens || $J${"font-display": "var(--font-mono)"}$J$::jsonb
WHERE key = 'wave-01';

UPDATE theme SET layout = $J${
  "tiles": {
    "marquee":      { "col": 2,  "row": 1,  "colSpan": 38, "rowSpan": 3 },
    "identity":     { "col": 2,  "row": 5,  "colSpan": 10, "rowSpan": 4 },
    "music":        { "col": 14, "row": 5,  "colSpan": 14, "rowSpan": 4 },
    "waveSwitcher": { "col": 30, "row": 5,  "colSpan": 5,  "rowSpan": 4 },
    "freshness":    { "col": 36, "row": 5,  "colSpan": 4,  "rowSpan": 4 },
    "latestDrop":   { "col": 1,  "row": 10, "colSpan": 12, "rowSpan": 7 },
    "calendar":     { "col": 1,  "row": 18, "colSpan": 12, "rowSpan": 6 },
    "today":        { "col": 14, "row": 10, "colSpan": 14, "rowSpan": 14 },
    "stats":        { "col": 29, "row": 10, "colSpan": 6,  "rowSpan": 7 },
    "ride":         { "col": 29, "row": 18, "colSpan": 6,  "rowSpan": 6 },
    "photoDrops":   { "col": 36, "row": 10, "colSpan": 4,  "rowSpan": 14 },
    "projects":     { "col": 2,  "row": 25, "colSpan": 13, "rowSpan": 4 },
    "social":       { "col": 17, "row": 25, "colSpan": 9,  "rowSpan": 4 },
    "hero":         { "col": 28, "row": 25, "colSpan": 12, "rowSpan": 4 }
  },
  "mobileOrder": ["identity", "today", "music", "calendar", "stats", "ride", "latestDrop", "photoDrops", "projects", "social", "hero", "marquee", "freshness"]
}$J$::jsonb
WHERE key = 'wave-02';
